REVOKE SELECT ON public.reportes FROM authenticated;
DO $$ DECLARE cols text; BEGIN SELECT string_agg(quote_ident(column_name),',') INTO cols FROM information_schema.columns WHERE table_schema='public' AND table_name='reportes' AND column_name NOT IN ('responsaveis_apurados','evidencia_apuracao','conclusao'); EXECUTE 'GRANT SELECT ('||cols||') ON public.reportes TO authenticated'; END $$;
DROP POLICY IF EXISTS central_ficheiros_read ON public.reporte_ficheiros; CREATE POLICY central_ficheiros_read ON public.reporte_ficheiros FOR SELECT TO authenticated USING(estado='ligado' AND public.central_ver(reporte_id) AND (fase<>'apuracao' OR public.central_gestor()) AND (resposta_id IS NULL OR public.central_gestor() OR uploader_id=public.rc_meu_funcionario_id()));
CREATE OR REPLACE FUNCTION public.central_storage_ver(p_bucket text,p_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p_bucket='central-reportes' THEN EXISTS(SELECT 1 FROM public.reporte_ficheiros a WHERE a.caminho=p_path AND a.estado='ligado' AND public.central_ver(a.reporte_id) AND (a.fase<>'apuracao' OR public.central_gestor()) AND (a.resposta_id IS NULL OR public.central_gestor() OR a.uploader_id=public.rc_meu_funcionario_id())) WHEN p_bucket='qualidade' THEN EXISTS(SELECT 1 FROM public.reportes r WHERE public.central_ver(r.id) AND EXISTS(SELECT 1 FROM unnest(r.anexos) u WHERE position('/qualidade/'||p_path IN u)>0)) OR EXISTS(SELECT 1 FROM public.reporte_eventos e WHERE public.central_ver(e.reporte_id) AND (e.tipo<>'decisao' OR public.central_gestor()) AND EXISTS(SELECT 1 FROM unnest(e.anexos) u WHERE position('/qualidade/'||p_path IN u)>0)) OR EXISTS(SELECT 1 FROM public.checklist_respostas c JOIN public.checklist_execucoes x ON x.id=c.execucao_id JOIN public.checklist_templates t ON t.id=x.template_id WHERE position('/qualidade/'||p_path IN coalesce(c.foto_url,''))>0 AND (public.central_gestor() OR public.rc_pertence_setor(t.setor_id))) OR EXISTS(SELECT 1 FROM public.checklist_itens i JOIN public.checklist_templates t ON t.id=i.template_id WHERE (public.central_gestor() OR public.rc_pertence_setor(t.setor_id)) AND EXISTS(SELECT 1 FROM unnest(i.instrucao_media) u WHERE position('/qualidade/'||p_path IN u)>0)) ELSE false END; $$;